def comps(a,col):
    ys,xs=np.where(a==col); pts=set(zip(ys,xs)); seen=set(); out=[]
    for p in pts:
        if p in seen: continue
        q=deque([p]); seen.add(p); n=0
        while q:
            y,x=q.popleft(); n+=1
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    r=(y+dy,x+dx)
                    if r in pts and r not in seen: seen.add(r); q.append(r)
        out.append(n)
    return sorted(out,reverse=True)
