def largest_object_color_square(grid):
    """3x3 square filled with the color of the largest single-component object."""
    from collections import Counter,deque
    a=[list(r) for r in grid]; h,w=len(a),len(a[0])
    best=None;bn=0
    for col in {v for r in a for v in r if v}:
        pts={(y,x) for y in range(h) for x in range(w) if a[y][x]==col}
        seen=set();q=deque([next(iter(pts))]);seen.add(q[0]);ok=True
        while q:
            y,x=q.popleft()
            for dy in(-1,0,1):
                for dx in(-1,0,1):
                    r=(y+dy,x+dx)
                    if r in pts and r not in seen: seen.add(r);q.append(r)
        if len(seen)==len(pts) and len(pts)>bn: bn=len(pts);best=col
    return [[best]*3 for _ in range(3)]
